@app.route('/settings/<role>')
@login_required
def settings(role):
    """Settings page for each role"""
    role = (role or '').strip().lower().replace('-', ' ')
    user_role = session.get('role', '').lower()
    is_technician = user_role == 'technician'
    
    # Validate role access
    if role in ('head of institution', 'deputy head of institution'):
        if user_role != role and not is_technician:
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))
        
        return render_template('dashboards/settings_principal.html', role=user_role)
    
    elif role == 'curriculum coordinator':
        # Allow broader schedule-management roles to access
        schedule_management_roles = ['curriculum coordinator', 'head of institution', 'deputy head of institution', 'super admin', 'accountant', 'technician']
        if user_role not in schedule_management_roles:
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))

        # Curriculum Coordinator settings (academic schedule management).
        connection = get_db_connection()
        settings = {}
        settings_profiles = []
        academic_levels = []
        selected_profile_id = request.args.get('profile_id', '').strip()
        if connection:
            try:
                with connection.cursor() as cursor:
                    cursor.execute("""
                        SELECT id, level_category, level_name
                        FROM academic_levels
                        WHERE COALESCE(level_status, 'active') = 'active'
                        ORDER BY level_category, level_name ASC
                    """)
                    academic_levels = cursor.fetchall() or []

                    try:
                        cursor.execute("""
                            SELECT id, profile_name, applicable_levels, is_active, updated_at,
                                   study_days, class_time_allocation, class_duration, activity_time_allocation
                            FROM academic_coordinator_settings
                            ORDER BY is_active DESC, updated_at DESC, id DESC
                        """)
                        has_is_active = True
                    except Exception:
                        cursor.execute("""
                            SELECT id, profile_name, applicable_levels, updated_at,
                                   study_days, class_time_allocation, class_duration, activity_time_allocation
                            FROM academic_coordinator_settings
                            ORDER BY updated_at DESC, id DESC
                        """)
                        has_is_active = False
                    profile_rows = cursor.fetchall() or []
                    for row in profile_rows:
                        if isinstance(row, dict):
                            raw_profile_levels = row.get('applicable_levels') or '[]'
                            profile_id = row.get('id')
                            profile_name = row.get('profile_name') or f'Profile {profile_id}'
                            is_active = bool(row.get('is_active')) if has_is_active else False
                            raw_study_days = row.get('study_days') or ''
                            raw_class_times = row.get('class_time_allocation') or '[]'
                            raw_activities = row.get('activity_time_allocation') or '[]'
                            profile_class_duration = row.get('class_duration') or 60
                        else:
                            raw_profile_levels = row[2] if row[2] else '[]'
                            profile_id = row[0]
                            profile_name = row[1] if row[1] else f'Profile {profile_id}'
                            is_active = bool(row[3]) if has_is_active and len(row) > 3 else False
                            offset = 5 if has_is_active else 4
                            raw_study_days = row[offset] if len(row) > offset and row[offset] else ''
                            raw_class_times = row[offset + 1] if len(row) > (offset + 1) and row[offset + 1] else '[]'
                            profile_class_duration = row[offset + 2] if len(row) > (offset + 2) and row[offset + 2] else 60
                            raw_activities = row[offset + 3] if len(row) > (offset + 3) and row[offset + 3] else '[]'

                        try:
                            parsed_profile_levels = json.loads(raw_profile_levels)
                        except Exception:
                            parsed_profile_levels = []
                        try:
                            parsed_class_times = json.loads(raw_class_times)
                        except Exception:
                            parsed_class_times = []
                        try:
                            parsed_activities = json.loads(raw_activities)
                        except Exception:
                            parsed_activities = []
                        parsed_days = [d.strip() for d in str(raw_study_days).split(',') if str(d).strip()]

                        settings_profiles.append({
                            'id': profile_id,
                            'profile_name': profile_name,
                            'applicable_levels': parsed_profile_levels,
                            'is_active': is_active,
                            'study_days': parsed_days,
                            'class_times': parsed_class_times if isinstance(parsed_class_times, list) else [],
                            'activities': parsed_activities if isinstance(parsed_activities, list) else [],
                            'class_duration': int(profile_class_duration) if str(profile_class_duration).isdigit() else 60,
                        })

                    # Determine which profile to load (query param, then active, then latest)
                    selected_id = None
                    if selected_profile_id.isdigit():
                        selected_id = int(selected_profile_id)
                    elif settings_profiles:
                        active_profile = next((p for p in settings_profiles if p.get('is_active')), None)
                        selected_id = active_profile['id'] if active_profile else settings_profiles[0]['id']

                    if selected_id:
                        cursor.execute("""
                            SELECT id, profile_name, study_days, applicable_levels, class_time_allocation, class_duration, activity_time_allocation
                            FROM academic_coordinator_settings
                            WHERE id = %s
                            LIMIT 1
                        """, (selected_id,))
                    else:
                        cursor.execute("""
                            SELECT id, profile_name, study_days, applicable_levels, class_time_allocation, class_duration, activity_time_allocation
                            FROM academic_coordinator_settings
                            ORDER BY updated_at DESC, id DESC
                            LIMIT 1
                        """)
                    result = cursor.fetchone()
                    if result:
                        if isinstance(result, dict):
                            settings = result
                            raw_levels = settings.get('applicable_levels') or '[]'
                            try:
                                settings['applicable_levels'] = json.loads(raw_levels)
                            except Exception:
                                settings['applicable_levels'] = []
                            if settings.get('class_time_allocation'):
                                try:
                                    settings['class_times'] = json.loads(settings['class_time_allocation'])
                                except Exception:
                                    settings['class_times'] = []
                            else:
                                settings['class_times'] = []
                            if settings.get('activity_time_allocation'):
                                try:
                                    settings['activities'] = json.loads(settings['activity_time_allocation'])
                                except Exception:
                                    settings['activities'] = []
                            else:
                                settings['activities'] = []
                        else:
                            applicable_levels_json = result[3] if result[3] else '[]'
                            class_times_json = result[4] if result[4] else '[]'
                            activities_json = result[6] if result[6] else '[]'
                            try:
                                applicable_levels = json.loads(applicable_levels_json)
                            except Exception:
                                applicable_levels = []
                            try:
                                class_times = json.loads(class_times_json)
                            except Exception:
                                class_times = []
                            try:
                                activities = json.loads(activities_json)
                            except Exception:
                                activities = []
                            settings = {
                                'id': result[0],
                                'profile_name': result[1] if result[1] else '',
                                'study_days': result[2] if result[2] else '',
                                'applicable_levels': applicable_levels,
                                'class_time_allocation': class_times_json,
                                'class_times': class_times,
                                'class_duration': result[5] if result[5] else '',
                                'activity_time_allocation': activities_json,
                                'activities': activities
                            }
            except Exception as e:
                print(f"Error fetching academic coordinator settings: {e}")
                settings['activities'] = []
            finally:
                connection.close()

        if 'activities' not in settings:
            settings['activities'] = []
        if 'class_times' not in settings:
            settings['class_times'] = []
        if 'applicable_levels' not in settings:
            settings['applicable_levels'] = []
        if 'profile_name' not in settings:
            settings['profile_name'] = ''
        if 'id' not in settings:
            settings['id'] = ''

        return render_template(
            'dashboards/settings_academic_coordinator.html',
            role=user_role,
            settings=settings,
            settings_profiles=settings_profiles,
            academic_levels=academic_levels
        )
    
    elif role == 'employee':
        employee_settings_roles = [r for r in EMPLOYEE_SUB_ROLES if r not in ('head of institution', 'super admin')]
        if user_role not in employee_settings_roles:
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))
        
        return render_template('dashboards/settings_employee.html', role=user_role)
    
    elif role in ['student', 'parent']:
        if user_role != role:
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))
        
        return render_template(f'dashboards/settings_{role}.html', role=role)
    
    else:
        flash('Invalid role.', 'error')
        return redirect(url_for('home'))

# Profile Update Routes
@app.route('/profile/employee/update', methods=['POST'])
@login_required
def update_employee_profile():
    """Update employee profile information"""
    user_role = session.get('role', '').lower()
    if user_role not in EMPLOYEE_SUB_ROLES:
        flash('You do not have permission to perform this action.', 'error')
        return redirect(url_for('home'))
    
    full_name = request.form.get('full_name', '').strip().upper()
    email = request.form.get('email', '').strip().lower()
    phone = request.form.get('phone', '').strip().upper()
    id_number = request.form.get('id_number', '').strip().upper()
    
    if not all([full_name, email, phone]):
        flash('Please fill in all required fields.', 'error')
        return redirect(url_for('profile', role='employee'))
    
    # Handle profile picture upload
    profile_picture = None
    if 'profile_picture' in request.files:
        file = request.files['profile_picture']
        if file and file.filename != '' and allowed_file(file.filename):
            # Generate unique filename
            timestamp = datetime.now().strftime('%Y%m%d%H%M%S')
            employee_id = session.get('employee_id') or session.get('user_id')
            filename = secure_filename(file.filename)
            file_ext = filename.rsplit('.', 1)[1].lower() if '.' in filename else 'jpg'
            unique_filename = f"{employee_id}_{timestamp}_{filename}"
            
            # Save file
            file_path = os.path.join(UPLOAD_FOLDER, unique_filename)
            file.save(file_path)
            profile_picture = f"uploads/profiles/{unique_filename}"
    
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                employee_id = session.get('employee_id') or session.get('user_id')
                
                # Get current profile picture to delete old one if new one is uploaded
                old_profile_picture = None
                if profile_picture:
                    cursor.execute("SELECT profile_picture FROM employees WHERE id = %s OR employee_id = %s", 
                                 (employee_id, employee_id))
                    result = cursor.fetchone()
                    if result and result.get('profile_picture'):
                        old_profile_picture = result.get('profile_picture')
                
                # Update employee profile
                if profile_picture:
                    cursor.execute("""
                        UPDATE employees 
                        SET full_name = %s, email = %s, phone = %s, id_number = %s, profile_picture = %s
                        WHERE id = %s OR employee_id = %s
                    """, (full_name, email, phone, id_number, profile_picture, employee_id, employee_id))
                    
                    # Delete old profile picture if it exists
                    if old_profile_picture:
                        old_file_path = os.path.join('static', old_profile_picture)
                        if os.path.exists(old_file_path):
                            try:
                                os.remove(old_file_path)
                            except Exception as e:
                                print(f"Error deleting old profile picture: {e}")
                    
                    # Update session with new profile picture
                    session['profile_picture'] = profile_picture
                else:
                    cursor.execute("""
                        UPDATE employees 
                        SET full_name = %s, email = %s, phone = %s, id_number = %s
                        WHERE id = %s OR employee_id = %s
                    """, (full_name, email, phone, id_number, employee_id, employee_id))
                
                connection.commit()
                
                # Update session
                session['full_name'] = full_name
                session['email'] = email
                
                flash('Profile updated successfully!', 'success')
        except Exception as e:
            print(f"Error updating employee profile: {e}")
            import traceback
            traceback.print_exc()
            connection.rollback()
            flash('An error occurred while updating your profile. Please try again.', 'error')
        finally:
            connection.close()
    else:
        flash('Database connection error. Please try again later.', 'error')
    
    return redirect(url_for('profile', role='employee'))

# Employee password change via email verification code
@app.route('/settings/employee/password/send-code', methods=['POST'])
@login_required
def send_employee_password_change_code():
    """Send a 6-digit verification code to the logged-in employee's email."""
    user_role = session.get('role', '').lower()
    employee_settings_roles = [r for r in EMPLOYEE_SUB_ROLES if r not in ('head of institution', 'deputy head of institution', 'super admin')]
    if user_role not in employee_settings_roles:
        flash('You do not have permission to perform this action.', 'error')
        return redirect(url_for('home'))

    connection = get_db_connection()
    if not connection:
        flash('Database connection error. Please try again later.', 'error')
        return redirect(employee_staff_settings_url('employee'))

    try:
        with connection.cursor() as cursor:
            employee_id = session.get('employee_id') or session.get('user_id')
            cursor.execute(
                "SELECT id, full_name, email FROM employees WHERE id = %s OR employee_id = %s LIMIT 1",
                (employee_id, employee_id),
            )
            employee = cursor.fetchone()
            if not employee or not (employee.get('email') if isinstance(employee, dict) else employee[2]):
                flash('No email address is linked to your account. Update your profile email first.', 'error')
                return redirect(employee_staff_settings_url('employee'))

            full_name = employee.get('full_name') if isinstance(employee, dict) else employee[1]
            email = employee.get('email') if isinstance(employee, dict) else employee[2]
            email_norm = normalize_login_email(email)

            code = ''.join(secrets.choice('0123456789') for _ in range(6))
            code_hash = generate_password_hash(code)
            expires_at = datetime.utcnow() + timedelta(minutes=30)

            if not send_password_reset_email(email_norm, full_name or 'User', code):
                flash(
                    'Could not send the verification email. Your school can set SMTP under Integration Settings, '
                    'or the server administrator can set MAIL_* environment variables.',
                    'error',
                )
                return redirect(employee_staff_settings_url('employee'))

            cursor.execute("""
                DELETE FROM password_reset_tokens
                WHERE LOWER(TRIM(email)) = %s AND account_type = 'employee' AND consumed_at IS NULL
            """, (email_norm,))
            cursor.execute("""
                INSERT INTO password_reset_tokens (email, account_type, account_id, code_hash, expires_at)
                VALUES (%s, 'employee', %s, %s, %s)
            """, (email_norm, employee.get('id') if isinstance(employee, dict) else employee[0], code_hash, expires_at))
            connection.commit()

            session['pwd_reset_email'] = email_norm
            flash('We sent a 6-digit code to your email. Enter it below to confirm the password change.', 'success')
            return redirect(employee_staff_settings_url('employee'))
    except Exception as e:
        print(f"send_employee_password_change_code error: {e}")
        try:
            connection.rollback()
        except Exception:
            pass
        flash('An error occurred while sending the verification code. Please try again.', 'error')
        return redirect(employee_staff_settings_url('employee'))
    finally:
        try:
            connection.close()
        except Exception:
            pass

# Settings Update Routes
@app.route('/settings/<role>/password', methods=['POST'])
@login_required
def update_password(role):
    """Update user password"""
    role = (role or '').strip().lower().replace('-', ' ')
    user_role = session.get('role', '').lower()
    
    if role in ('head of institution', 'deputy head of institution'):
        is_technician = user_role == 'technician'
        if user_role != role and not is_technician:
            flash('You do not have permission to perform this action.', 'error')
            return redirect(url_for('home'))
        
        current_password = request.form.get('current_password', '')
        new_password = request.form.get('new_password', '')
        confirm_password = request.form.get('confirm_password', '')
        
        if not all([current_password, new_password, confirm_password]):
            flash('Please fill in all password fields.', 'error')
            return redirect(employee_staff_settings_url(role))
        
        if new_password != confirm_password:
            flash('New passwords do not match.', 'error')
            return redirect(employee_staff_settings_url(role))
        
        if len(new_password) < 6:
            flash('Password must be at least 6 characters long.', 'error')
            return redirect(employee_staff_settings_url(role))
        
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    employee_id = session.get('employee_id') or session.get('user_id')
                    cursor.execute("SELECT password_hash FROM employees WHERE id = %s OR employee_id = %s", 
                                 (employee_id, employee_id))
                    employee = cursor.fetchone()
                    
                    if employee and check_password_hash(employee['password_hash'], current_password):
                        new_password_hash = generate_password_hash(new_password)
                        cursor.execute("""
                            UPDATE employees 
                            SET password_hash = %s
                            WHERE id = %s OR employee_id = %s
                        """, (new_password_hash, employee_id, employee_id))
                        connection.commit()
                        flash('Password updated successfully!', 'success')
                    else:
                        flash('Current password is incorrect.', 'error')
            except Exception as e:
                print(f"Error updating password: {e}")
                connection.rollback()
                flash('An error occurred while updating your password. Please try again.', 'error')
            finally:
                connection.close()
        else:
            flash('Database connection error. Please try again later.', 'error')
        
        return redirect(employee_staff_settings_url(role))
    
    elif role == 'employee':
        employee_settings_roles = [r for r in EMPLOYEE_SUB_ROLES if r not in ('head of institution', 'deputy head of institution', 'super admin')]
        if user_role not in employee_settings_roles:
            flash('You do not have permission to perform this action.', 'error')
            return redirect(url_for('home'))

        reset_code = (request.form.get('reset_code') or '').strip().replace(' ', '')
        current_password = request.form.get('current_password', '')
        new_password = request.form.get('new_password', '')
        confirm_password = request.form.get('confirm_password', '')

        if not all([new_password, confirm_password]):
            flash('Please fill in the new password fields.', 'error')
            return redirect(employee_staff_settings_url('employee'))

        if new_password != confirm_password:
            flash('New passwords do not match.', 'error')
            return redirect(employee_staff_settings_url('employee'))

        if len(new_password) < 6:
            flash('Password must be at least 6 characters long.', 'error')
            return redirect(employee_staff_settings_url('employee'))

        connection = get_db_connection()
        if not connection:
            flash('Database connection error. Please try again later.', 'error')
            return redirect(employee_staff_settings_url('employee'))

        try:
            with connection.cursor() as cursor:
                employee_id = session.get('employee_id') or session.get('user_id')
                cursor.execute(
                    "SELECT id, password_hash, email FROM employees WHERE id = %s OR employee_id = %s LIMIT 1",
                    (employee_id, employee_id),
                )
                employee = cursor.fetchone()
                if not employee:
                    flash('Employee account not found.', 'error')
                    return redirect(employee_staff_settings_url('employee'))

                employee_db_id = employee.get('id') if isinstance(employee, dict) else employee[0]
                employee_email = employee.get('email') if isinstance(employee, dict) else employee[2]
                email_norm = normalize_login_email(employee_email)

                # Preferred: verify by 6-digit email code (no current password required)
                if reset_code:
                    if (not reset_code.isdigit()) or len(reset_code) != 6:
                        flash('Verification code must be a 6-digit number.', 'error')
                        return redirect(employee_staff_settings_url('employee'))

                    cursor.execute("""
                        SELECT * FROM password_reset_tokens
                        WHERE LOWER(TRIM(email)) = %s
                          AND account_type = 'employee'
                          AND account_id = %s
                          AND consumed_at IS NULL
                          AND expires_at > %s
                        ORDER BY id DESC
                        LIMIT 1
                    """, (email_norm, employee_db_id, datetime.utcnow()))
                    token_row = cursor.fetchone()
                    if not token_row or not check_password_hash(token_row['code_hash'], reset_code):
                        flash('Invalid or expired verification code. Please request a new code.', 'error')
                        return redirect(employee_staff_settings_url('employee'))

                    new_password_hash = generate_password_hash(new_password)
                    cursor.execute(
                        "UPDATE employees SET password_hash = %s WHERE id = %s",
                        (new_password_hash, employee_db_id),
                    )
                    if getattr(cursor, "rowcount", 0) < 1:
                        try:
                            connection.rollback()
                        except Exception:
                            pass
                        flash(
                            'Password change could not be saved (no rows updated). '
                            'This usually means the app is connected to a different database/user than the one you are checking.',
                            'error',
                        )
                        return redirect(employee_staff_settings_url('employee'))
                    cursor.execute(
                        "UPDATE password_reset_tokens SET consumed_at = %s WHERE id = %s",
                        (datetime.utcnow(), token_row['id']),
                    )
                    connection.commit()
                    flash('Password updated successfully!', 'success')
                    return redirect(employee_staff_settings_url('employee'))

                # Fallback: current password (keeps older UI/clients working)
                if not current_password:
                    flash('Enter your current password or request a 6-digit verification code.', 'error')
                    return redirect(employee_staff_settings_url('employee'))

                stored_hash = employee.get('password_hash') if isinstance(employee, dict) else employee[1]
                if not stored_hash or not check_password_hash(stored_hash, current_password):
                    flash('Current password is incorrect.', 'error')
                    return redirect(employee_staff_settings_url('employee'))

                new_password_hash = generate_password_hash(new_password)
                cursor.execute(
                    "UPDATE employees SET password_hash = %s WHERE id = %s",
                    (new_password_hash, employee_db_id),
                )
                if getattr(cursor, "rowcount", 0) < 1:
                    try:
                        connection.rollback()
                    except Exception:
                        pass
                    flash(
                        'Password change could not be saved (no rows updated). '
                        'This usually means the app is connected to a different database/user than the one you are checking.',
                        'error',
                    )
                    return redirect(employee_staff_settings_url('employee'))
                connection.commit()
                flash('Password updated successfully!', 'success')
                return redirect(employee_staff_settings_url('employee'))
        except Exception as e:
            print(f"Error updating password: {e}")
            try:
                connection.rollback()
            except Exception:
                pass
            flash('An error occurred while updating your password. Please try again.', 'error')
            return redirect(employee_staff_settings_url('employee'))
        finally:
            try:
                connection.close()
            except Exception:
                pass
    
    elif role == 'curriculum coordinator':
        schedule_management_roles = ['curriculum coordinator', 'head of institution', 'deputy head of institution', 'super admin', 'accountant', 'technician']
        if user_role not in schedule_management_roles:
            flash('You do not have permission to perform this action.', 'error')
            return redirect(url_for('home'))

        current_password = request.form.get('current_password', '')
        new_password = request.form.get('new_password', '')
        confirm_password = request.form.get('confirm_password', '')

        if not all([current_password, new_password, confirm_password]):
            flash('Please fill in all password fields.', 'error')
            return redirect(employee_staff_settings_url('curriculum coordinator'))

        if new_password != confirm_password:
            flash('New passwords do not match.', 'error')
            return redirect(employee_staff_settings_url('curriculum coordinator'))

        if len(new_password) < 6:
            flash('Password must be at least 6 characters long.', 'error')
            return redirect(employee_staff_settings_url('curriculum coordinator'))

        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    employee_id = session.get('employee_id') or session.get('user_id')
                    cursor.execute("SELECT password_hash FROM employees WHERE id = %s OR employee_id = %s",
                                   (employee_id, employee_id))
                    employee = cursor.fetchone()

                    if employee and check_password_hash(employee['password_hash'], current_password):
                        new_password_hash = generate_password_hash(new_password)
                        cursor.execute("""
                            UPDATE employees
                            SET password_hash = %s
                            WHERE id = %s OR employee_id = %s
                        """, (new_password_hash, employee_id, employee_id))
                        connection.commit()
                        flash('Password updated successfully!', 'success')
                    else:
                        flash('Current password is incorrect.', 'error')
            except Exception as e:
                print(f"Error updating password: {e}")
                connection.rollback()
                flash('An error occurred while updating your password. Please try again.', 'error')
            finally:
                connection.close()
        else:
            flash('Database connection error. Please try again later.', 'error')

        return redirect(employee_staff_settings_url('curriculum coordinator'))

    elif role in ['student', 'parent']:
        if user_role != role:
            flash('You do not have permission to perform this action.', 'error')
            return redirect(url_for('home'))
        
        # Similar logic for student/parent password update
        flash('Password update functionality for students and parents will be implemented soon.', 'info')
        return redirect(url_for('settings', role=role))
    
    else:
        flash('Invalid role.', 'error')
        return redirect(url_for('home'))

