            with connection.cursor() as cursor:
                cursor.execute("""
                    INSERT INTO academic_levels 
                    (level_category, level_name, level_code, level_description, level_status)
                    VALUES (%s, %s, %s, %s, %s)
                """, (level_category, level_name, level_code, level_description, level_status_value))
